<template>
    <Marco titulo="Historial de pedidos" icono="fas fa-table">
        <div class="container-fluid">
            <div class="row">
                <div class="col-md-3">
                    <div class="row">
                        <div class="col-md-12">
                            <h3 class="sub-cajero"><button type="button" class="btn btn-success" @click="getPedidosArray()"><i class="fas fa-sync-alt"></i></button> Pedidos</h3>
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-md-12">
                            <input type="text" class="form-control input-style" placeholder="Buscar..." v-model="buscaPedido">
                        </div>
                    </div>
                    <div class="contenedor-pedidos">
                        <ContainerPedidos v-for="item in matchPedidos" v-bind:key="item.venta_producto" :pedidoObj="item" @sendPedidoMethod="showDatosPedido"></ContainerPedidos>
                    </div>
                </div>
                <div class="col-md-9">
                    <div class="row">
                        <div class="col-md-6">
                            <div class="row">
                                <div class="col-md-12">
                                    <h5 class="sub-cajero">Detalle <span class="style-titulo-pedido" v-if="nro_pedido!=0">PEDIDO # {{nro_pedido}}</span></h5>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-12">
                                    <div class="table-responsive">
                                        <table class="table table-bordered table-condensed">
                                            <thead class="head-table">
                                                <tr>
                                                    <th scope="col">Cant</th>
                                                    <th scope="col">Detalle</th>
                                                    <th scope="col">P.Unit</th>
                                                    <th scope="col">Importe</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-for="prod in datosComanda" v-bind:key="prod.id_producto">
                                                    <td>{{prod.cantidad}}</td>
                                                    <td>{{prod.nombre_producto}}</td>
                                                    <td>{{parseFloat(prod.p_unit).toFixed(2)}}</td>
                                                    <td>{{parseFloat(prod.importe).toFixed(2)}}</td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-12">
                                    <div class="table-responsive">
                                        <table class="table table-bordered table-condensed">
                                            <thead class="head-table">
                                                <tr>
                                                    <th scope="col">Importe total</th>
                                                    <th>{{ datosComanda.length > 0 ? parseFloat(datosComanda[0].total).toFixed(2) : "" }} {{ datosComanda.length > 0 ? datosComanda[0].tipo_moneda : "" }}</th>
                                                </tr>
                                            </thead>
                                        </table>
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-12">
                                    <button type="button" class="btn btn-danger btn-block" v-if="nro_pedido!=0" @click="cancelarPedidoMethod()">Cancelar Pedido</button>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-12 pos-order-actions mt-2">
                                    <button class="btn btn-danger" v-if="nro_pedido!=0" @click="printTicket(false)" style="width: 50%; background-color: #800080; border-color: #800080;"><i class="fas fa-print"></i> Imprimir Cocina</button>
                                    <button class="btn btn-danger" v-if="nro_pedido!=0" @click="printTicket(true)" style="width: 50%; background-color: #c62828; border-color: #c62828;"><i class="fas fa-print"></i> Imprimir Cliente</button>
                                </div>
                            </div>
                        </div>
                        <div class="col-md-6">
                            <h5 class="sub-cajero">Cliente</h5>
                            <div class="table-responsive">
                                <table class="table table-bordered table-striped table-condensed">
                                    <tbody>
                                        <tr>
                                            <td scope="col">Señor(a)</td>
                                            <td>{{datosComanda.length > 0 ? datosComanda[0].nombre_cliente : ""}}</td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                            <div class="table-responsive" v-if="type_user == 1">
                                <!-- Modulo de pagos -->
                                <table class="table table-bordered table-striped table-condensed">
                                    <tbody>
                                        <tr>
                                            <td scope="col" class="subtituloPedidos">Tipo de pago</td>
                                            <td class="subtituloPedidos"></td>
                                        </tr>
                                        <tr>
                                            <!-- inicio tipo de pago -->
                                                <ul class="mb-0 mt-0" style="list-style: none;">
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_pago" v-model="selectedTipoPago" id="checkEfectivo" :value=codTipoPago.efectivo disabled>
                                                        <label class="form-check-label" for="checkEfectivo">
                                                            Efectivo
                                                        </label>
                                                    </li>
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_pago" v-model="selectedTipoPago" id="checkQR" :value=codTipoPago.qr disabled>
                                                        <label class="form-check-label" for="checkQR">Pago QR</label>
                                                    </li>
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_pago" v-model="selectedTipoPago" id="checkTarjeta" :value=codTipoPago.tarjeta disabled>
                                                        <label class="form-check-label" for="checkTarjeta">
                                                            Tarjeta
                                                        </label>
                                                    </li>
                                                </ul>
                                                <!-- fin tipo de pago -->
                                        </tr>
                                        <tr>
                                            <td scope="col" class="subtituloPedidos">Tipo de servicio</td>
                                            <td class="subtituloPedidos"></td>
                                        </tr>
                                        <tr>
                                            <!-- inicio tipo de servicio -->
                                                <ul class="mb-0 mt-0" style="list-style: none;">
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_servicio" v-model="selectedTipoServicio" id="checkMesa" :value=codTipoServicio.mesa disabled>
                                                        <label class="form-check-label" for="checkMesa">
                                                            Mesa
                                                        </label>
                                                    </li>
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_servicio" v-model="selectedTipoServicio" id="checkDelivery" :value=codTipoServicio.delivery disabled>
                                                        <label class="form-check-label" for="checkDelivery">
                                                            Delivery
                                                        </label>
                                                    </li>
                                                    <li class="li-horizontal">
                                                        <input class="form-check-input" type="radio" name="tipo_servicio" v-model="selectedTipoServicio" id="checkTakeAway" :value=codTipoServicio.take_away disabled>
                                                        <label class="form-check-label" for="checkTakeAway">
                                                            Para llevar
                                                        </label>
                                                    </li>
                                                </ul>
                                                <!-- fin tipo de servicio -->
                                        </tr>
                                        <tr v-if="selectedTipoPago == 0 && datosComanda.length > 0">
                                            <td scope="col"><i class="far fa-money-bill-alt"></i> Efectivo</td>
                                            <td>
                                                <input type="number" class="form-control" v-model="datosComanda[0].efectivo" disabled>
                                            </td>
                                        </tr>
                                        <tr v-if="datosComanda.length > 0">
                                            <td scope="col"><i class="fas fa-money-bill-wave"></i> Importe</td>
                                            <td>
                                                <input type="number" class="form-control" v-model="datosComanda[0].total" disabled>
                                            </td>
                                        </tr>
                                        <tr v-if="selectedTipoPago == 0 && datosComanda.length > 0">
                                            <td scope="col"><i class="fab fa-cc-visa"></i> Cambio</td>
                                            <td>
                                                <input type="number" class="form-control" v-model="datosComanda[0].cambio" disabled>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div> 
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <AlertModal
            v-model="showCancelModal"
            title="Confirmación de cancelación"
            :showCancel="true"
            confirmText="Sí, cancelar"
            cancelText="No"
            type="warning"
            @confirm="confirmCancel"
            @cancel="cancelCancel"
        >
            <div>¿Desea cancelar el Pedido # {{ datosComanda.length > 0 ? datosComanda[0].nro_pedido : 0 }}?</div>
        </AlertModal>
        <LoadingModal :value="progressDepth>0" message="Cargando..." />
    </Marco>
</template>

<script>
const axios = require("axios");
import Marco from '@/components/Layout/Marco';
import Pagination from '@/components/Pagination/Pagination';
import Modal from '@/components/Modal/Modal';
import BoxMessage from '@/components/Messages/BoxMessage';
import ListErrors from '@/components/Messages/ListErrors';
import ContainerPedidos from '@/components/Cajero/ContainerPedidos';
import {misMixins} from '@/mixins/misMixins.js';
import flatPickr from 'vue-flatpickr-component';
import 'flatpickr/dist/flatpickr.css';
import {renderFrameComanda} from '@/utils/printcomandas.js';
import AlertModal from '@/components/Modal/AlertModal.vue';
import { progressMixin } from '@/mixins/progressMixin';
import LoadingModal from '@/components/Modal/LoadingModal.vue';

export default{
    name: 'HistorialPedidos',
    components: {
        Marco,
        BoxMessage,
        Modal,
        flatPickr,
        ListErrors,
        Pagination,
        ContainerPedidos,
        //facturaCocina
        AlertModal,
        LoadingModal
    },

    data() {
        return {
            data_usr: {},
            pedidosArray: [],
            nro_pedido: 0,
            buscaPedido: '',
            sw: false,
            type_user: this.$store.state.type_user,
            isForCustomer: false,
            selectedTipoPago: null,
            codTipoPago: {
                efectivo: 0,
                tarjeta: 1,
                qr: 2
            }, //0 efectivo, 1 tarjeta, 2 qr
            selectedTipoServicio: null,
            codTipoServicio: {
                mesa: 0,
                delivery: 1,
                take_away: 2
            }, //0 mesa, 1 delivery, 2 take away
            showCancelModal: false,
            cancelCtx: {},
            datosComanda: []
        }
    },

    mixins: [misMixins, progressMixin],
    computed: {
        matchPedidos: function() {
            return this.pedidosArray.filter(pedido=>{
                let b = this.buscaPedido.trim().toUpperCase()
                //let a = pedido.dni_cliente.toUpperCase()
                let c = pedido.nombre_completo
                if(c == null){
                    c = ''
                }
                let e = c.toUpperCase()
                let i = pedido.id_venta_producto.toString()
                return e.match(b) || i.match(b);
            });
        },
        tipoMoneda() {
            return this.$store.state.restauranteData.tipo_moneda
        },
        getIdentificacion(){
            return this.$store.state.restauranteData.identificacion
        }
    },
    created () {
        this.progressStart()
        this.getDataUser(this.type_user).then(response => {
            this.data_usr = response.data;
            this.getPedidosArray();
            this.progressFinish()
        }).catch(error => {
            this.$toasted.show(error, {type: 'error', duration: 1000})
            this.progressFail()
        });
    },
    methods: {
        getPedidosArray(){
            this.progressStart()
            let url = ''
            if(this.type_user == 0){//mozo
                url = this.$store.state.url_root+`api/auth/ventaproductos/mozo/${this.data_usr.id_mozo}/sucursal/${this.data_usr.id_sucursal}`
            }else{
                url = this.$store.state.url_root+`api/auth/ventaproductos/caja/${this.data_usr.id_caja}`
            }
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.get(url)
            .then(response => {
                this.pedidosArray = response.data.data
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("HistorialPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        showDatosPedido(obj){
            if(this.$refs.statePrint != null){
                this.$refs.statePrint.checked = false;
            }
            this.isForCustomer = false;
            this.progressStart()
            this.nro_pedido = obj.nro_venta
            this.$store.dispatch('indicePedidosActiveAction', obj.id_venta_producto)
            let url = this.$store.state.url_root+`api/auth/productovendido/pedido/${obj.id_venta_producto}`
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.get(url)
            .then(response => {
                this.datosComanda = response.data.datosComanda
                if(response.data.datosComanda.length > 0){
                    this.selectedTipoPago = response.data.datosComanda[0].cod_tipo_pago
                    this.selectedTipoServicio = response.data.datosComanda[0].cod_tipo_servicio
                }
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("HistorialPedido.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        cleanOrder(){
            this.nro_pedido = 0;
            this.selectedTipoPago = null;
            this.selectedTipoServicio = null;
            this.datosComanda = [];
        },
        changeStateIsForCustomer(){
            if(this.$refs.statePrint.checked){
                this.isForCustomer = true
            }else{
                this.isForCustomer = false
            }
        },
        printTicket(x){
            let dataForOrderTicket = {
                id_venta_producto: this.datosComanda[0].id_venta_producto,
                nroPedido_ticket: this.datosComanda[0].nro_pedido,
                isForCustomer: x,
                numero_whatsapp: this.data_usr.whatsapp_cocina,
                prefijo: this.data_usr.prefijo,
                datosComanda: this.datosComanda
            }
            // Exponer data para el botón de WhatsApp
            window.currentComandaData = dataForOrderTicket;
            renderFrameComanda();
             // Obtener el PDF
            const loadingToast = this.$toasted.show('Cargando comprobante...', { 
                type: 'info',
                duration: null // No se cierra automáticamente
            });

            let _dataForOrderTicket = dataForOrderTicket;
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.post(this.$store.state.url_root + 'api/auth/printcomanda', _dataForOrderTicket, { responseType: 'blob' })
            .then(response => {
                const file = new Blob([response.data], { type: 'application/pdf' });
                const fileURL = URL.createObjectURL(file);
                const iframe = document.getElementById('pdfIframe');
                iframe.src = fileURL;
                loadingToast.goAway(0); // Cerrar mensaje de carga
            })
            .catch (error => {
                this.$toasted.show("NuevoPedido: "+error, {type: 'error', duration: 1000})
            });
        },
        cancelarPedidoMethod(){
            this.showCancelModal = true
        },
        confirmCancel(){
            if (!this.datosComanda.length > 0) {
                this.$toasted.show("No se encontraron datos de la comanda", {type: 'error', duration: 1000})
                return
            }
            this.progressStart()
            const payload = { ...this.datosComanda[0], estado_venta: 1 }
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.post(this.$store.state.url_root+`api/auth/updateventaproducto`, payload)
            .then(response => {
                let pedido = response.data.data;
                let index = this.pedidosArray.findIndex(item => item.id_venta_producto === pedido.id_venta_producto);
                if (index !== -1) {
                    this.pedidosArray.splice(index, 1);
                }

                this.$toasted.show(`Pedido # ${this.datosComanda[0].nro_pedido} cancelado correctamente`, {type: 'success', duration: 1000})
                this.cleanOrder();
                this.progressFinish()
                this.showCancelModal = false
            })
            .catch (error => {
                this.$toasted.show(`Error al cancelar el pedido # ${this.datosComanda[0].nro_pedido}`, {type: 'error', duration: 1000})
                this.progressFail()
                this.showCancelModal = false
            });
        },
        cancelCancel(){
            this.showCancelModal = false
        }
    },
}
</script>

<style lang="scss">
    .subtituloPedidos{
        font-weight: bold;
    }
    .margin-buttons{
        margin-bottom: 10px;
        button{
            margin: 0px 0px 3px 3px;
        }
    }
    .style-titulo-pedido{
        background: greenyellow;
        //opacity: 0.5;
        color: black;
    }
    .contenedor-pedidos{
        max-height: 35rem;
        border: 1px solid #a5a4a4;
        overflow: auto;
        padding: 3px;
        margin-top: 4px;
        margin-bottom: 20px;
    }
</style>