<template>
    <Marco titulo="Apertura/Cierre de caja" icono="fas fa-table">
        <div class="container-fluid">
            <div class="row">
                <div class="col-12">
                    <div class="mobile-header">
                        <BoxMessage :message="nuevoHistorialMsg" :cod="'su'" icono="fas fa-check"></BoxMessage>
                        <button type="button" class="btn btn-primary btn-apertura" data-toggle="modal" data-target="#modalAperturaCaja">
                            <i class="fas fa-plus"></i> 
                            <span class="btn-text">Apertura</span>
                        </button>
                    </div>
                </div>
            </div>
            <div class="row">
                <div class="col-12">
                    <div class="table-controls">
                        <label class="entries-label">
                            Entradas
                            <select id="nroEntradas" @change="cambiaOption" ref="nroEntradas" class="form-select">
                                <option>3</option>
                                <option>6</option>
                                <option>10</option>
                            </select>
                        </label>
                    </div>
                </div>
            </div>
            <div class="row">
                <div class="col-md-12">
                    <div class="table-responsive">
                        <table-component
                            :data="listaHistorial"
                            tableClass="table table-mobile"
                            theadClass="head-table"
                            filterPlaceholder="Buscar..."
                            filter-input-class="inputSearchText"
                            :show-caption=false
                            >
                        <table-column show="fecha" label="Fecha" :tdClass="'mobile-date'"></table-column>
                        <table-column show="monto_inicial" :label="'Apertura ('+tipoMoneda+')'" :tdClass="'mobile-amount'"></table-column>
                        <table-column show="monto" :label="'Actual ('+tipoMoneda+')'" :tdClass="'mobile-amount'"></table-column>
                        <table-column label="Acciones" :sortable="false" :filterable="false" :tdClass="'mobile-actions'">
                            <template slot-scope="row">
                                <div class="action-buttons">
                                    <button type="button" class="btn btn-sm btn-success action-btn" :class="{disabled: !row.estado}" @click="updateCashAmount(row.id_historial_caja)" title="Actualizar">
                                        <i class="fas fa-sync-alt"></i>
                                    </button>
                                    <button type="button" class="btn btn-sm btn-danger action-btn" :class="{disabled: !row.estado}" @click="cashClosing(row.id_historial_caja, row.fecha, row.monto_inicial)" title="Cerrar">
                                        <i class="fas fa-window-close"></i>
                                    </button>
                                </div>
                            </template>
                        </table-column>
                        </table-component>
                    </div>
                </div>
            </div>
            <div class="row">
                <div class="col-md-12 table-responsive">
                    <Pagination :pagination="pagination" v-on:funcion="getAllAperturaCierre"></Pagination>
                </div>
            </div>
        </div>
        <!-- Ventanas Modales -->
        <form @submit.prevent="createHistoryCash">
            <Modal titulo="Apertura de Caja" :icono="'fas fa-folder-plus'" idModal="modalAperturaCaja">
                <template v-slot:body>
                    <div class="container-fluid">
                        <div class="row">
                            <BoxMessage :message="datosRepetidos" :cod="'da'" icono="fas fa-exclamation-circle"></BoxMessage>
                            <div class="col-12">
                                <div class="form-group">
                                    <label for="" class="label-style">Monto Inicial ({{tipoMoneda}})</label>
                                    <input type="text" class="form-control input-style" v-model="historial.monto_inicial">
                                    <ListErrors :errores="errores.monto_inicial"></ListErrors>
                                </div>
                            </div>
                        </div>
                    </div>
                </template>
                <template v-slot:footer>
                    <button type="button" class="btn btn-secondary" data-dismiss="modal" @click="limpiaHistorial">Cerrar</button>
                    <button type="submit" class="btn btn-primary" ref="nuevoAperturaBtn">Guardar</button>
                </template>
            </Modal>
        </form>
        <AlertModal
            v-model="showCloseModal"
            title="Confirmación de cierre"
            :showCancel="true"
            confirmText="Sí, cerrar"
            cancelText="No"
            type="warning"
            @confirm="confirmClose"
            @cancel="cancelClose"
        >
            <div>Esta seguro que desea cerrar la caja de fecha {{ closeCtx.fecha }}?</div>
        </AlertModal>
        <LoadingModal :value="progressDepth>0" message="Cargando..." />
    </Marco>
</template>

<script>
const axios = require("axios");
import Marco from '@/components/Layout/Marco';
import Pagination from '@/components/Pagination/Pagination';
import Modal from '@/components/Modal/Modal';
import BoxMessage from '@/components/Messages/BoxMessage';
import ListErrors from '@/components/Messages/ListErrors';
import {misMixins} from '@/mixins/misMixins.js';
import flatPickr from 'vue-flatpickr-component';
import 'flatpickr/dist/flatpickr.css';
import AlertModal from '@/components/Modal/AlertModal.vue';
import { progressMixin } from '@/mixins/progressMixin';
import LoadingModal from '@/components/Modal/LoadingModal.vue';

export default{
    name: 'AperturaCierre',
    components: {
        Marco,
        BoxMessage,
        Modal,
        flatPickr,
        ListErrors,
        Pagination,
        AlertModal,
        LoadingModal
    },

    data() {
        return {
            nro_page: 3,
            pagination: {},
            data_usr: {},
            listaHistorial: [],
            errores: {},
            historial: {},
            nuevoHistorialMsg: '',
            datosRepetidos: '',
            date: new Date(),
            config: {
                wrap: true, // set wrap to true only when using 'input-group'
                altFormat: 'j/n/Y',
                altInput: true,
                dateFormat: 'Y-m-d',
                allowInput: true,
                wrap: false,
                static: true     
            },
            cajaHistorialArray: [],
            showCloseModal: false,
            closeCtx: {}
        }
    },

    mixins: [misMixins, progressMixin],
    computed: {
        tipoMoneda() {
            return this.$store.state.restauranteData.tipo_moneda
        }
    },
    created () {
        this.progressStart()
        this.getDataUser(1).then(response => {
            this.data_usr = response.data;
            this.getAllAperturaCierre();
            this.progressFinish()
        }).catch(error => {
            this.$toasted.show(error, {type: 'error', duration: 1000})
            this.progressFail()
        });
    },
    methods: {
        getAllAperturaCierre(page) {
            this.progressStart()
            let base = this.$store.state.url_root+`api/auth/historialcaja/caja/${this.data_usr.id_caja}/page/${this.nro_page}`
            let url = (page && Number(page) > 0) ? `${base}?page=${page}` : base
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.get(url)
            .then(response => {
                this.listaHistorial = response.data.data.data;
                this.pagination = response.data.data;
                this.progressFinish()
            })
            .catch (error => {
                this.$toasted.show("AperturaCierre.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        },
        limpiaHistorial(){
            this.historial = {}
            this.errores = {}
            this.datosRepetidos = ''
            //this.nuevoHistorialMsg = ''
        },
        createHistoryCash(){
            this.$refs.nuevoAperturaBtn.className = "btn btn-primary disabled"
            this.progressStart()
            this.historial.id_cajero = this.data_usr.id_cajero;
            this.historial.estado = true;
            this.historial.id_caja = this.data_usr.id_caja;
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.post(this.$store.state.url_root+`api/auth/historialcaja/${this.data_usr.id_caja}`, this.historial)
            .then(response => {
                if(response.data.error == null){
                    this.getAllAperturaCierre()
                    this.nuevoHistorialMsg = `Se aperturo la caja en fecha ${response.data.data.fecha}`
                    this.limpiaHistorial();
                    window.$("#modalAperturaCaja").modal('hide');
                    this.progressFinish()
                    this.$refs.nuevoAperturaBtn.className = "btn btn-primary"
                }else{
                    if(response.data.error.valores != null){
                        this.datosRepetidos = response.data.error.valores;
                    }else{
                        this.errores = response.data.error;
                    }
                    this.progressFail()
                    this.$refs.nuevoAperturaBtn.className = "btn btn-primary"
                }
            })
            .catch(error => {
                this.$toasted.show("AperturaCierre.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
                this.$refs.nuevoAperturaBtn.className = "btn btn-primary"
            })
        },
        cambiaOption(){
            this.nro_page = this.$refs.nroEntradas.value
            this.getAllAperturaCierre()
        },
        cashClosing(id, fecha, monto_inicial){
            this.closeCtx = { id, fecha, monto_inicial }
            this.showCloseModal = true
        },
        confirmClose(){
            this.progressStart()
            this.historial.id_cajero = this.data_usr.id_cajero;
            this.historial.estado = false;
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.put(this.$store.state.url_root+`api/auth/cashclosing/${this.closeCtx.id}`, this.historial)
            .then(response => {
                let hcaja = response.data.data;
                let index = this.listaHistorial.findIndex(item => item.id_historial_caja === hcaja.id_historial_caja);
                if (index !== -1) {
                    hcaja.monto = parseFloat(hcaja.monto).toFixed(2);
                    hcaja.estado = false;
                    this.listaHistorial.splice(index, 1, hcaja);
                }

                this.nuevoHistorialMsg = `Se cerro la caja de fecha ${this.closeCtx.fecha}`
                this.limpiaHistorial();
                this.progressFinish()
                this.showCloseModal = false
            })
            .catch (error => {
                this.$toasted.show("AperturaCaja.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
                this.showCloseModal = false
            });
        },
        cancelClose(){
            this.showCloseModal = false
        },

        updateCashAmount(idHistorialCaja){
            this.progressStart()    
            let url = this.$store.state.url_root+`api/auth/updatecashamount/${idHistorialCaja}`
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.get(url)
            .then(response => {
                let hcaja = response.data.data
                let index = this.listaHistorial.findIndex(item => item.id_historial_caja === hcaja.id_historial_caja);
                if (index !== -1) {
                    hcaja.monto = parseFloat(hcaja.monto).toFixed(2);
                    this.listaHistorial.splice(index, 1, hcaja);
                }
                this.progressFinish();
            })
            .catch (error => {
                this.$toasted.show("AperturaCaja.vue: "+error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        }
    },
}
</script>

<style lang="scss" scoped>
