<template>
    <Marco titulo="Cambiar contraseña" icono="fas fa-table">
        <div class="container">
            <BoxMessage :message="msgChangeWhatsapp" :cod="'su'" icono="fas fa-check-circle"></BoxMessage>
            <form @submit.prevent="updateWhatsapp()">
            <div class="row">
                <div class="col-md-6">
                    <div class="form-group">
                        <label for="" class="label-style">Prefijo sucursal</label>
                        <input type="text" class="form-control" v-model="data_usr.prefijo" :disabled="true">
                    </div>
                </div>
                <div class="col-md-6">
                    <div class="form-group">
                        <label for="" class="label-style">WhatsApp cocina</label>
                        <input type="text" class="form-control" v-model="data_usr.whatsapp_cocina" :disabled="true">
                    </div>
                </div>
            </div>
            <div class="row">
                <div class="col-md-6">
                    <div class="form-group">
                        <label for="" class="label-style">Prefijo nuevo:</label>
                        <input type="text" class="form-control" v-model="whatsapp.nuevo_prefijo">
                        <ListErrors :errores="errores.nuevo_prefijo"></ListErrors>
                    </div>
                </div>
                <div class="col-md-6">
                    <div class="form-group">
                        <label for="" class="label-style">WhatsApp nuevo:</label>
                        <input type="text" class="form-control" v-model="whatsapp.nuevo_numero">
                        <ListErrors :errores="errores.nuevo_numero"></ListErrors>
                    </div>
                </div>
            </div>
            <div class="row">
                <div class="col-md-12">
                    <button class="btn btn-primary" type="submit">Cambiar</button>
                </div>
            </div>
            </form>
        </div>
        <LoadingModal :value="progressDepth>0" message="Cargando..." />
    </Marco>
</template>
<script>
const axios = require("axios");
import Marco from '@/components/Layout/Marco';
import {misMixins} from '@/mixins/misMixins.js';
import BoxMessage from '@/components/Messages/BoxMessage';
import ListErrors from '@/components/Messages/ListErrors';
import { progressMixin } from '@/mixins/progressMixin';
import LoadingModal from '@/components/Modal/LoadingModal.vue';

export default{
    name: 'WhatsappCocina',
    components: {
        Marco,
        BoxMessage,
        ListErrors,
        LoadingModal
    },
    data() {
        return {
            data_usr: {},
            msgChangeWhatsapp: '',
            errores: {},
            whatsapp: {
                nuevo_prefijo: null,
                nuevo_numero: null
            }
        }
    },
    created () {
        this.progressStart()
        this.getDataUser(this.$store.state.type_user).then(response => {//cajero
            this.data_usr = response.data;
            this.progressFinish()
        }).catch(error => {
            this.$toasted.show(error, {type: 'error', duration: 1000})
            this.progressFail()
        });
    },
    mixins: [misMixins, progressMixin],
    methods: {
        cleanData(){
            this.errores = {};
            this.whatsapp = {
                nuevo_prefijo: null,
                nuevo_numero: null
            }
        },
        updateWhatsapp(){
            this.progressStart()
            axios.defaults.headers.common["Authorization"] = "Bearer " + this.$store.state.token;
            axios.put(this.$store.state.url_root+`api/auth/changewhatsapp/${this.data_usr.id_sucursal}`, this.whatsapp)
            .then(response => {
                console.log(response.data)
                if(!response.data.error){
                    this.data_usr.prefijo= response.data.data.prefijo;
                    this.data_usr.whatsapp_cocina= response.data.data.whatsapp_cocina;
                    this.msgChangeWhatsapp = 'El whatsapp se cambio correctamente'
                    this.progressFinish()
                    this.cleanData()
                }else{
                    console.log("Esta ingresando por los errores");
                    console.log(response.data.error)
                    this.errores = response.data.error;
                    console.log("Errores: ", this.errores)
                    this.progressFail();
                }
            }).catch(error => {
                this.$toasted.show(error, {type: 'error', duration: 1000})
                this.progressFail()
            });
        }
    },
}
</script>