<template>
    <div class="autenticacion-marco container-fluid">
        <div class="row">
            <div class="col-md-12 text-center">
                <a class="navbar-brand" href="#">
                    <img alt="Perfil Usuario" src="../../assets/ServiFast.png" width="300" class="img-fluid"/><br>
                    <span>Sistema de restobar</span>
                </a>
            </div>          
        </div>
        <div class="row">
            <div class="col-md-12">
                <BoxMessage :message="advertenciaLogin" :cod="'wa'"></BoxMessage>
                <form action="#" @submit.prevent="login">
                    <div class="form-group">
                        <div class="borde-input">
                            <i class="fas fa-user"></i>
                            <input type="text" class="form-control" v-model="nombre_usuario" placeholder="Usuario">
                        </div>
                        <ListErrors :errores="errores.nombre_usuario"></ListErrors>
                    </div>
                    <div class="form-group">
                        <div class="borde-input">
                            <i class="fas fa-unlock"></i>
                            <input :type="showPassword ? 'text' : 'password'" class="form-control" v-model="password" placeholder="Contraseña">
                            <button type="button" class="btn-toggle-password" @click="togglePassword">
                                <i :class="showPassword ? 'fas fa-eye-slash' : 'fas fa-eye'"></i>
                            </button>
                        </div>
                        <ListErrors :errores="errores.password"></ListErrors>
                    </div>
                    <div class="form-group d-flex justify-content-center">
                        <button type="submit" class="btn-login">Ingresar</button>
                    </div>
                </form>
            </div>
        </div>
    </div>
</template>
<script>
    import ListErrors from '@/components/Messages/ListErrors'
    import BoxMessage from '@/components/Messages/BoxMessage'
    import { progressMixin } from '@/mixins/progressMixin';
    export default{
        name: 'AutenticacionSuperAdmin',
        components: {
            ListErrors,
            BoxMessage
        },
        data() {
            return {
                nombre_usuario: '',
                password: '',
                errores: {},
                advertenciaLogin: '',
                type_user: 3,
                showPassword: false
            }
        },
        mixins: [progressMixin],
        methods: {
            togglePassword() {
                this.showPassword = !this.showPassword
            },
            login() {
                this.progressStart()
                this.errores = {};
                if(this.type_user != null){
                    this.$store.dispatch('retrieveToken', {
                        nombre_usuario: this.nombre_usuario,
                        password: this.password,
                        type_user: this.type_user
                    }).then(response =>{
                        if(response.data.access_token != null && response.data.access_token != ''){
                            this.$router.push({name: 'restaurant'})
                            this.progressFinish()
                        }
                        else if(response.data.error != null){
                            this.advertenciaLogin = response.data.error;
                            this.progressFail()
                        }
                        else{
                            this.errores = response.data.errors;
                            this.progressFail()
                        }
                    }).catch((error) => {
                        this.$toasted.show("Error en el servidor: "+error, {type: 'error', duration: 1000});
                        this.progressFail()
                    })
                }else{
                    this.errores.type_user = ['Debe asignar el tipo de usuario'];
                    this.progressFail();
                }
            }
        },
    }
</script>
<style lang="scss">
    .autenticacion-marco{
        background-color: transparent;
        padding: 1rem;
        a{
            font-size: 20px;
            color: white;
            margin-bottom: 1rem;
            span{
                opacity: 0.5;
            }
        }
        label{
            color: #D3D3D3;
        }
        input[type="text"]{
            border-style: none;
            background-color: transparent;
            color: #D3D3D3;
            &::placeholder{
                color: #D3D3D3;
                opacity: 1;
            }
            &:focus{
                box-shadow: none;
            }
        }
        input[type="password"]{
            border-style: none;
            background-color: transparent;
            color: #D3D3D3;
            &::placeholder{
                color: #D3D3D3;
                opacity: 1;
            }
            &:focus{
                box-shadow: none;
            }
        }
        .borde-input{
            border-bottom: 2px solid #D3D3D3;
            display: flex;
            align-items: center;
            i{
                line-height: 38px;
                width: 1.5rem;
                text-align: center;
                color: #D3D3D3;
            }
            .btn-toggle-password{
                background: transparent;
                border: none;
                color: #D3D3D3;
                cursor: pointer;
                padding: 0 10px;
                font-size: 14px;
                &:focus{
                    outline: none;
                    box-shadow: none;
                }
                &:hover{
                    color: white;
                }
            }
        }
        .btn-login{
            border-style: none;
            background-color: transparent;
            border: 1px solid #D3D3D3;
            padding: 15px;
            border-radius: 8px;
            color: #D3D3D3;
            &:focus{
                box-shadow: none;
            }
        }
    }
</style>